package main
import (
 "fmt"
 "os"
 "github.com/onflow/cadence/common"
 "github.com/onflow/cadence/runtime"
 runutils "github.com/onflow/cadence/test_utils/runtime_utils"
)
func main() {
 source,err:=os.ReadFile("hello.cdc")
 if err!=nil { panic(err) }
 r:=runtime.NewRuntime(runtime.Config{})
 ctx:=runtime.Context{Interface:&runutils.TestRuntimeInterface{}, Location:common.ScriptLocation{1}}
 result,err:=r.ExecuteScript(runtime.Script{Source:source},ctx)
 if err!=nil { panic(err) }
 fmt.Println(result)
}
